(window.webpackJsonp=window.webpackJsonp||[]).push([[100],{541:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、禁食总是与悲伤联系在一起的。其中尤其包括了因犯罪而有的悲伤、后悔，虽然不限于此。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、你的心是怎么样的？这是一切的起点。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、但在耶稣的时代，犹太人对禁食这个外在行为的含义已经重新进行了解释。对于他们而言，禁食不是因为自己悲伤、为罪痛悔，而是一种在神面前称义的方法。这就是臭名昭著的律法主义：我可以做点什么，来在神面前获得认可。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、耶稣说“旧的”衣服、“旧的”皮袋，指的就是当时的犹太人对禁食、对人的外在行为的那种律法主义式的观念。这种观念是犹太教的核心。而“新的”衣服、“新的”皮袋，指的是他自己将带来的观念。他所带来的这种观念是不能与犹太教的观念兼容的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、在律法主义观念下，行为本身是逻辑起点、关注焦点：禁食是人得以在神面前称义的一种工具，我禁食了，就可以仗着称义。那么自然，我要关注的就是我是不是禁食了，我一周几次禁食。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("6、耶稣却认为，如果心里不悲伤就不用禁食，悲伤的时候才需要禁食。所以在这样的一种观念下，逻辑起点不是这个外在行为，而是你的内心状态。既然如此，那么我们关注的焦点，也不是你外在做了什么，而是你的内心是怎么样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("7、虽然耶稣在用给了新和旧的对比，而犹太人的这种律法主义的观念是旧观念，但其实耶稣所带来的这种观念并不是什么新观念，反而是一种更旧的观念，是深深扎根在旧约中的，从西奈山开始就有的观念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("8、堕落的人，是不愿意承认只有在与神的关系正确的情况下，才可能行出善来的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("9、律法主义表现形形色色，其存在也根深蒂固：你在做出行为的时候，会不会去关注你的动机和你的心态？还是说，你做了就做了，没有意识到在错误的动机和心态下的做出的行为是犯罪，因此你自然也就不会去认罪，也不会去悔改。如果是这样，那你就已经被律法主义毒害了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("10、要摆脱律法主义的控制，要刻意去操练：就是不断去关注自己做出行为内心的层面，是不是为了荣耀神、是不是依靠着神？这也不是装出来的，是要内心的流露。因此还得再往下走，你要真的看到自己在神面前是什么鬼样子、神为你做了什么、给了你什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("11、如果我们把灵性的成长比喻为练功的话，这些都是硬功夫。不是靠你每周参加几次查经、聚会能够获得的。需要你沉下心来，单独花时间与神相处、反思自己每个行为背后的内心状态、在作出每个行为之前先关注自己的起心动念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。今天我们继续来讲路加福音5:33~39。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、禁食的本意")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先我们来看第33节。这里的“他们”是指30节说的法利赛人和文士。所以这件事和5：29~30节讲到的，耶稣和税吏、罪人一起吃饭是在同一个场景之下。法利赛人一方面质疑耶稣进行吃喝交际的对象，另一方面也质疑耶稣进行吃喝交际的时间。如果我们去看马可福音2:18的平行经文就知道，那个时候他们正处在禁食期间。当时来质疑耶稣的除了法利赛人，还有约翰的门徒。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从他们的问题可以看到，无论是法利赛人还是约翰的门徒——或者我们归纳起来，就是当时的宗教人士——是常常进行禁食的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("实际上，摩西律法中只向以色列人规定了一次禁食的时间，就是在赎罪日。利未记23：26~32节记载，耶和华晓谕摩西说： “七月初十是赎罪日，你们要守为圣会，并要刻苦己心，也要将火祭献给耶和华。当这日，什么工都不可做，因为是赎罪日，要在耶和华你们的神面前赎罪。当这日，凡不刻苦己心的，必从民中剪除。凡这日做什么工的，我必将他从民中除灭。你们什么工都不可做。这在你们一切的住处作为世世代代永远的定例。你们要守这日为圣安息日，并要刻苦己心，从这月初九日晚上到次日晚上，要守为安息日。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("禁食就是这里说的“刻苦己心”的表现形式之一。赎罪日，顾名思义也知道，是特别为自己、为整个族群的罪来忏悔、悲伤、寻求神赦免的日子。所以禁食，最开始就是在赎罪日表达内心因为犯罪得罪神而有的悲伤、忏悔，寻求神的赦免。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("后来以色列人也把这种表达悲伤的方式扩展到赎罪日之外。比如在士师记20章，提到以色列人十一个支派与便雅悯支派间发生内战。一连两日，十一支派都被便雅悯人打败，被杀了三万人。在26节说以色列众人就上到伯特利，坐在耶和华面前哭号，当日禁食直到晚上。这里通过哭号、禁食，表达对战争失利的悲伤。在当时犹太人眼中，战争失利就意味着失去了耶和华的祝福。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("再比如在撒母耳记下第1章，大卫听到扫罗和约拿单被杀的消息，第11节说他“撕裂衣服，而且悲哀哭号，禁食到晚上，是因扫罗和他儿子约拿单，并耶和华的民以色列家，倒在刀下”。大卫也是在这里以禁食的方式表示自己的悲伤和哀痛。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一些经文看上去似乎不是太有表达悲伤的意味，而是更强调通过禁食来寻求耶和华的帮助，但这些禁食中，其实是带着认罪、忏悔、为罪悲伤的成分的。因为在以色列人看来，遭受不幸与神离弃他们了有很大的关系，而神离弃他们的原因就是因为他们违背了与神的约，犯了罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("比如在历代志下第20章，记载摩押人、亚扪人、米乌尼人一起来攻击犹大。第3节说犹大王约沙法就惧怕，定意寻求耶和华，在犹大全地宣布禁食。这段经文侧重于强调约沙法通过禁食来寻求耶和华的帮助。但我们来看第6~12节约沙法的祷告，他不断呼求神记念自己与以色列祖先的约。在第8~9节，他引用了所罗门的祷告：“他们住在这地，又为你的名建造圣所，说：‘倘有祸患临到我们，或刀兵灾殃，或瘟疫饥荒，我们在急难的时候站在这殿前向你呼求，你必垂听而拯救，因为你的名在这殿里。’”这里似乎看不到认罪、悲伤的含义。但当我们去看列王纪下第8章，所罗门当时的祷告，本身是包含着认罪、为罪悲伤的内容的，在列王纪下8：37~39节，所罗门在献殿的时候祷告说：“国中若有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌犯境围困城邑，无论遭遇什么灾祸疾病，你的民以色列，或是众人，或是一人，自觉有罪，向这殿举手，无论祈求什么，祷告什么，求你在天上你的居所垂听赦免。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们看到，当约沙法宣告禁食、引用所罗门的祷告，实际上是代表众人认罪，求神从他天上的居所垂听赦免。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("到了被掳之后，为了记念整个民族犯罪被神惩戒，当时犹太人特别发展出了四次固定的禁食时间，分别是在每年四月、五月、七月、十月。这在撒迦利亚书第8章里面有记载。撒迦利亚书19节说：“万军之耶和华如此说：四月、五月禁食的日子，七月、十月禁食的日子，必变为犹大家欢喜快乐的日子和欢乐的节期，所以你们要喜爱诚实与和平。”这里神通过撒迦利亚给犹太人一个应许，就是他们每年这四次禁食的日子，会变为欢乐的日子。可见当时，这四次禁食是悲伤的日子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("其中10月的禁食，是记念尼布甲尼撒王在10月开始围攻耶路撒冷（公元前588年）；4月的禁食，是记念尼布甲尼撒在4月攻破耶路撒冷（公元前586年）；5月的禁食，是纪念5月圣殿被毁；7月禁食，是记念基大利被杀。基大利是尼布甲尼撒在犹太人中所选立的省长。当时留在巴勒斯坦地区的犹太人把他杀了之后，因为害怕巴比伦人的报复，所以都逃往埃及。耶和华要把他们赶出应许之地的预言就全部实现了。上面我们说的月份都是犹太历而不是公历。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("犹太人通过禁食来记念这四个日子，其实就是要在禁食中为自己的祖先犯罪而悲伤，在禁食中反省自己民族的罪，求神回转赦免。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("希望从这些背景的介绍中，大家能够对禁食的意义有正确的理解。禁食总是与悲伤联系在一起的。当然，其中尤其包括了因犯罪而有的悲伤、后悔，虽然不限于此。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("明白了这一点，大家就能明白在今天的经文中，耶稣对法利赛人的第一个回答。在路加福音5：34他说：“新郎和陪伴之人同在的时候，岂能叫陪伴之人禁食呢？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先我们不要忘了，法利赛人这是在进行弥赛亚调查的第二阶段。所以当耶稣提到“新郎”的时候，他不仅是在做一个比喻，也是在提示他们注意他的身份。在先知书中，当预言神将会重新恢复以色列时，常常就是用新郎与新娘的关系来描述。在约翰福音第3章28~30节记载，施洗约翰当时也做见证说：“若不是从天上赐的，人就不能得什么。我曾说我不是基督，是奉差遣在他前面的，你们自己可以给我作见证。娶新妇的就是新郎，新郎的朋友站着，听见新郎的声音就甚喜乐。故此，我这喜乐满足了。他必兴旺，我必衰微。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣用这个比喻，在34节告诉他们：现在是新郎来娶妻的时候，是神恢复以色列的时候，那自然不是悲伤而是喜乐的时候。既然没有悲伤，那么为表达悲伤而有的禁食，就是不合时宜的。这里的宾客当然是指的就是门徒。在这个比喻中，他们是这场婚礼的见证人。弥赛亚来要恢复以色列，他们现在就像等候在婚礼开始之前的宾客一样，带着喜乐、带着期盼要见证这个盛大的时刻。如果大家参加过婚礼，我想都有这种感受。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣说，这时候没有理由禁食，那是不正常、不自然的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但紧接着，在第35节他也说到，这场婚礼并不会如人们预期那样举行。“但日子将到，新郎要离开他们。”我们从之后发生的事就会知道，这是指以色列人拒绝了他们的弥赛亚，把他钉死在十字架上。本来是要来见证一场盛大典礼的宾客们，看到的却是一出悲剧。他们心里当然会忧伤、难过、悲哀，这时禁食就是很自然、正常的事情了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，从刚才我对主耶稣对法利赛人这个回答的解释中，我们可以看到，他反复强调的是什么。禁食是一个外在的行为，而这个外在的行为一定要与禁食的人内心的状态相一致，这才是正常、自然的。喜乐的内心，就不会做出表达哀伤的行为；哀伤的内心，才会引出哀伤的行为。所以你的心是怎么样的？这是一切的起点。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、被重新定义的禁食")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你做出的外在行为和内心状态不一致，这只会有两种情况。第一种情况就是你是在装假；第二种情况，就是你在重新解释这个外在行为的含义。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而后一种情况，正是当时的犹太人对禁食这个行为所做的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们刚才已经介绍了，禁食在旧约中的本意是对内在悲伤的表达，尤其是因为罪而来的悲伤、痛悔。但在耶稣的时代，犹太人对禁食这个外在行为的含义已经重新进行了解释。我们来看路加福音第18章9~14节。第9节说耶稣是在向那些仗着自己是义人藐视别人的人，设一个比喻。这些人是怎么仗着自己是义人的呢？从耶稣的这个比喻中我们看到，这个法利赛人举出他为义的例子，包括了不勒索、不奸淫，也包括了一周禁食两次、还有做十一奉献。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从这里我们看到，这个法利赛人禁食不是因为自己悲伤、为罪痛悔，而是把禁食作为一种手段，仗着这种手段，他们认为自己在神面前就是义人了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天的经文中，路加福音5：33提到约翰的门徒和法利赛人常常禁食，我们不知道约翰的门徒是如何认识禁食的，但从耶稣这个比喻中我们可以看到，至少法利赛人——也就是当时的主流宗教人士，已经重新对禁食这个外在行为的意义进行了解释。这个行为不再是，或者不仅仅是一种对内心悲伤、为罪痛悔的外在表达，而变成了用以在神面前称义的一种方法了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果大家对神学稍微有所涉猎就知道，这就是臭名昭著的律法主义。也就是说，我可以做点什么，来在神面前获得认可。这种观念当时风行于犹太教，到后来也风行于天主教，现在也仍然潜藏在很多更正教（也就是我们中国所称的基督教）的教会、更正教的信徒当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、新观念旧观念")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们还是先回到耶稣那个时代。刚才已经说了，当时的犹太宗教人士已经深深地陷入了律法主义的泥潭当中，而他们对禁食这个旧约圣经中所提到的外在行为的理解，只不过是冰山的一角。所以当法利赛人在第33节问耶稣，你的门徒为什么不禁食的时候，和他们在第30节的逻辑是一脉相承的：都是在质疑他的弥赛亚身份。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在第30节，他们认为弥赛亚应该洁身自好，就像所有敬虔的宗教人士所做的，他们无法理解这位被宣称为弥赛亚的人怎么会和罪人一同坐席；同样，在第33节，他们认为弥赛亚应该教导他的跟随者遵守律法（这个律法当然就包括了犹太人当时认为的传统），这样才能被神所接纳，就像所有敬虔的宗教人士所做的。因此他们无法理解为什么他会放任门徒们在该禁食的时候吃吃喝喝。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("面对他们这样一种对外在行为的律法主义式的理解——刚才我们已经说了，所谓律法主义式的理解，就是认为外在行为是用以在神面前称义的工具——耶稣就又设了一个比喻，对他们说：“没有人把新衣服撕下一块来补在旧衣服上，若是这样，就把新的撕破了，并且所撕下来的那块新的和旧的也不相称。也没有人把新酒装在旧皮袋里，若是这样，新酒必将皮袋裂开，酒便漏出来，皮袋也就坏了。 但新酒必须装在新皮袋里。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里耶稣是用两个当时巴勒斯坦地区生活上的尝试来设比喻。我们首先来解释一下这里的意思。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣时代的布和我们现在的布不同，那时候没有那么多高科技，衣服洗了之后是会缩水的。而把新布补在旧衣服上，在洗的时候，新布和旧布的缩水程度不一样，就可能会再次把衣服撕破。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当时以色列的新酒，一般都是仍然在发酵的酒。就在发酵的过程中会产生很多气体，使装酒的皮袋发胀。如果是旧皮袋，那么它没有那么好的延展性，因此新酒装进去，发酵后就可能导致皮袋破裂，酒流出来，皮袋也坏了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，耶稣这里是用了两个例子。但路加说这是“一个”比喻而不是两个。就是说这两个例子说的是同一个事情：新的不能嫁接在旧的上面，新的不能和旧的协同，两者是不兼容的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣在这里所说“旧的”衣服、“旧的”皮袋，指的就是当时的犹太人对禁食、对人的外在行为的那种律法主义式的观念。这种观念是犹太教的核心。而“新的”衣服、“新的”皮袋，指的是他自己将带来的观念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣说，他所带来的这种观念是不能与犹太教的观念兼容的。因此，耶稣其实是在告诉他们：我知道你们现在是在对这场弥赛亚运动进行调查。但如果你们这些宗教人士要想真的认识我，认识这位神的代表，认识这位弥赛亚，你们必须要放弃掉自己那些固有的、旧的观念，你们不能用那些观念来理解我、来认识我、来解释我。我要带来的观念和你们的旧观念是不相容的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("犹太人当时的旧观念我们已经解释了：就是律法主义式的对外在行为的理解。在这种观念下，外在的行为决定了你是否能在神面前称义。因此，行为本身是他们的逻辑起点，也是他们关注的焦点。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这反映在他们对禁食的态度上。禁食是一个外在的行为。禁食是人得以在神面前称义的一种工具，我禁食了，就可以仗着称义。所以禁食这就是逻辑起点。那么自然，我要关注的就是我是不是禁食了，我一周几次禁食。看到没有，禁食也就成了我们关注的焦点。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而耶稣带来的新观念是什么呢？答案在5章第34节~35节。这段话刚才我已经解释了。耶稣说如果心里不悲伤就不用禁食，悲伤的时候才需要禁食。也就是说，禁食这对悲伤这种内心状态的表达。所以在这样的一种观念下，逻辑起点不是这个外在行为，而是你的内心状态。既然如此，那么我们关注的焦点，也不是你外在做了什么，而是你的内心是怎么样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家注意到没有？我们刚才对34~35节是怎么解释的？我们首先回顾了旧约中关于禁食的经文，我们看了一些旧约中禁食的例子，然后我们就知道禁食其实是和内心的悲伤联系在一起的，尤其是和对罪的悲伤、痛悔联系在一起的。带着这样的认识，我们就理解了为何弥赛亚来复兴以色列的时候，他的门徒们不需要悲伤从而禁食；在弥赛亚被以色列拒绝的时候，他们就会悲伤而禁食。然后我们就得到了一个结论：你的心是怎么样的，这是一切的起点。是不是？我们刚刚讲的。还记得吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们从旧约开始，很自然就得到了这个结论，对不对？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们看到，虽然耶稣在后面用给了新和旧的对比，而犹太人的这种律法主义的观念是旧观念，但其实耶稣所带来的这种观念并不是什么新观念，反而是一种更旧的观念，是深深扎根在旧约中的，从西奈山开始就有的观念。只是后来，犹太人把经念歪了，用一种新的观念去理解外在行为，然后这种观念持续了上百年，逐渐成为了社会主流，就变成了旧的观念了。当耶稣回归到摩西律法，回归到犹太人的历史去理解外在行为，把外在行为仅仅看做是内心状态的表现的时候，这种观念反而成了新的了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们把神和他子民的互动历史广义地称为教会历史的话，我们会看到一个比较有意思的现象。公元1世纪，主耶稣带来的观念，实际上不是新的，而是回归旧约，但却被视为是对犹太教的革新，他自己也说这是新的；公元16世纪，当马丁路德、加尔文他们发起宗教改革，实际上也不是新的，而是回归新约（当然最终也回归旧约，因为新约和旧约是一脉相承的），但也被认为是对天主教的革新，所形成的宗教，还被称为是新教。无论是主耶稣，还是马丁路德、加尔文，他们带来的其实都不是革新，而是返旧，返回到神所赐下的启示当中，而这个启示是从最开始就赐下的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以经常听到有人说，基督教是从犹太教分裂出来的，有很多人搞不清楚犹太教所信的神和我们所信的神有什么区别，甚至有人认为是同一个神。但实际上，我们信的神，和亚伯拉罕、以撒、雅各、摩西、大卫、以赛亚、但以理所信的是同一个神，而犹太教所信的，反而是另一个神，因为他们在某一个时间点上，带入了新的观念来认识这位神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个观念当然就是律法主义。就是认为可以仗着外在行为在神面前称义。就是把逻辑起点放在外在行为上，把关注的焦点放在外在行为上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("四、形形色色的律法主义")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这种观念有各种各样，形形色色的变种，我举几个例子，也许大家会从中看到你自己的身影：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当你走在路上，有个小朋友迎面跑来。突然他跌倒了，你去把他扶起来。这是不是一个善行？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你认为这是一个善行，你就已经与律法主义沾边了。因为你把逻辑起点、关注焦点放在这个外在行为上，而没有放在你做出这个行为内心的状态。我们上次讲了，什么才是善行？不是你主观上怎么认为，或者我主观上怎么认为，而是神在客观上怎么认为？弥迦书6:8，还记得吗？行公义、好怜悯、存谦卑的心，与神同行。所以内心的状态必须是怎么样的？你动机上必须是为了荣耀神，心态上必须是谦卑（当然，也必须带着对这个孩子的怜悯，这个没什么好说的）。如果你扶起这个小朋友，不是因为你敬畏神，要荣耀神，那么你这个内心的状态就是错误的，你这个行为在客观上也就不是善行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我再举一个例子。大家有没有听过这样的说法，或者甚至你自己也是这样认为的：基督教和中国的伦理是不矛盾的。我们中国讲究孝道，而圣经中也说要孝敬父母。我们中国讲究要终于忠于婚姻、忠于家庭，而圣经也说要好好照顾妻子、好好照顾孩子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你是这样想，那其实你也沾染上了律法主义的毒素。因为你还是关注在行为上，而没有去关注行为后面的心理是怎么样的。中国人当然要讲究孝道，但那后面的心理原因，不是因为敬畏神，而是因为孔子是这样训练我们的；中国人当然提倡忠于婚姻、忠于家庭，但那后面的心理原因，不是因为敬畏神，而是千百年来社会加给我们的责任感。这些世俗的伦理是旧衣服、旧皮袋，而耶稣所带来的是新布、新酒。新布不能缝在旧衣服上，新酒也不能装在旧皮袋中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以基督教与中国的伦理不是不矛盾的，而是完全不兼容的两个东西。如果你不能彻底抛弃掉这些世俗伦理带给你的影响，而是一看，他们对人外在行为的要求都是一样的啊，就欣然地把他们都一并接受，那你最终就是两头不是人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我就更不用再去举那些认为可以靠着自己的外在行而在神面前全部或者部分称义的人了。当他们做出某个外在行为——比如这些法利赛人做出禁食行为——当然也有一种内心的心理状态。但这心理不是存谦卑、荣耀神，而是存骄傲、亵渎神。因为他们认为自己的行为足够好，足以让神全部或者部分地悦纳；因为他们认为神不够圣洁、不够要求完美，因此他们在罪身中所做的行为，就已经足以配得上他的荣耀了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，你们看到没有？律法主义的表现形式多种多样。这种观念的特点就是有意去忽略人做出行为后面的心理状态，以行为本身为逻辑起点，关注在行为本身上，有没有禁食啦，有没有孝敬父母啦，有没有周日去教会啦，有没有照顾自己的妻子啦，有没有读经祷告啦，等等。为什么？因为一旦进入到后面的心理状态，你就需要检视自己与神的关系了。你爱他吗？你敬畏他吗？因此你是为了他做吗，是在与他同行吗？你是靠着他做，是存谦卑的心吗？如果不是。对不起，这不是善，这是恶。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("堕落的人，是不愿意承认只有在与神的关系正确的情况下，才可能行出善来的；堕落的人，是不愿意承认靠自己什么善事都做不了的。所以律法主义的幽灵可以说是亚当堕落之后，人类根深蒂固的观念。影响着每一个世代的每一个人，不仅影响着犹太人，也影响着中国人、德国人、美国人，不仅塑造了犹太教，也塑造了印度教、佛教、伊斯兰教、天主教、东正教、还有各种各样的宗教，并且也塑造着很多的更正教的人，甚至包括你，只是你没有意识到而已。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你去反思一下就会意识到我说的没有错：你在做出行为的时候，会不会去关注你的动机和你的心态？还是说，你做了就做了，没有意识到在错误的动机和心态下的做出的行为是犯罪，因此你自然也就不会去认罪，也不会去悔改。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("律法主义这种观念是非常难以摆脱的，所以主耶稣在5：39节说“没有人喝了陈酒又想喝新的，他总说陈的好。”这句话的意思就是，陈酒，那旧的观念——在这段禁食的经文、其实也包括下面的安息日的经文这样的上下文中，就是指这种以外在行为为逻辑起点和焦点的观念，是会紧紧抓住人，让人上瘾的。原因我已经说了，因为这符合人堕落的本性：就是骄傲、自以为可以独立于神存在。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么要摆脱这种观念的控制，必须要刻意进行操练。对陈酒上瘾的人，如何才能喜欢上新酒？那就是不喝陈酒，去不断喝新酒，去让自己适应新酒的味道。这是一种操练，既然是操练，就是需要时间、需要过程的，就不会是很舒服的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，要摆脱律法主义的控制，就是不断去关注自己做出行为内心的层面：你是不是为了荣耀神、是不是依靠着神？这也不是装出来的，是要内心的流露。因此要想真心荣耀神、依靠神，停留在知道这个理论也是不够的，还得再往下走，你要真的看到自己在神面前是什么鬼样子、神为你做了什么、给了你什么。因此默想自己的罪、默想神的圣洁、默想十字架、默想神的爱、默想天国，在默想中去向神认罪、向神感恩，去在神面前羞愧、伤痛、流泪、感动、欢喜。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们把灵性的成长比喻为练功的话，我说实话，这些都是硬功夫。这些不是靠你每周参加几次查经、聚会能够获得的。需要你沉下心来，单独花时间与神相处；需要你沉下心来，反思自己每个行为背后的内心状态；需要你沉下心来，在作出每个行为之前先关注自己的起心动念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们现在是处在一个资源很丰富，但也很浮躁的社会中。这也影响着教会。各种课程、各种书籍、各种讲道的视频、音频，唾手可得；各种活动、各种事工、各种聚会，也都很容易组织起来。这些是神的祝福。但如果你自己不能沉下心来，去操练刚才我说的这些硬功夫，那你是无法摆脱旧观念对你的控制的，而你获得的，不过就是建造在沙土、草木、禾秸之上的生命。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);